from pathlib import Path
import json,re,html,zipfile
import markdown
O=Path(__file__).resolve().parent;meta=json.loads((O/'metadata.json').read_text());chs=json.loads((O/'chapters.json').read_text())
body=markdown.markdown((O/'handbook.md').read_text(),extensions=['fenced_code','tables','toc'],output_format='html5')
# Restore original source whitespace after Markdown preprocessing expands tabs.
manifest=json.loads((O/'source-manifest.json').read_text())
source_index=iter(manifest)
def original_source(match):
    entry=next(source_index)
    return '<pre><code class="language-java">'+html.escape(entry['text'])+'\n</code></pre>'
body,count=re.subn(r'<pre><code class="language-java">.*?</code></pre>',original_source,body,flags=re.S)
assert count==len(manifest)
# Markdown raw H2 IDs are preserved; unique IDs for auto generated subheadings are provided by toc.
