nav=''.join(f'<a href="#{c["id"]}">{i+1:02d}. {html.escape(c["title"])}</a>' for i,c in enumerate(chs))
script='''
const menu=document.getElementById('menu'),aside=document.querySelector('aside');menu.onclick=()=>{aside.classList.toggle('open');menu.setAttribute('aria-expanded',String(aside.classList.contains('open')));};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{aside.classList.remove('open');menu.setAttribute('aria-expanded','false');});
try{if(localStorage.getItem('boot-theme')==='dark')document.documentElement.classList.add('dark');}catch(e){}
document.getElementById('theme').onclick=()=>{document.documentElement.classList.toggle('dark');try{localStorage.setItem('boot-theme',document.documentElement.classList.contains('dark')?'dark':'light')}catch(e){}};
document.querySelectorAll('pre').forEach(p=>{let b=document.createElement('button');b.className='copy';b.textContent='复制代码';b.onclick=async()=>{try{await navigator.clipboard.writeText(p.querySelector('code').textContent);b.textContent='已复制';setTimeout(()=>b.textContent='复制代码',1500)}catch(e){b.textContent='请选中代码复制'}};p.after(b);});
const viewer=document.getElementById('viewer');document.getElementById('viewer-close').onclick=()=>viewer.close();viewer.onclick=e=>{if(e.target===viewer)viewer.close()};document.querySelectorAll('.diagram').forEach(f=>{let svg=f.querySelector('svg'),wrap=document.createElement('div');wrap.className='diagram-wrap';svg.before(wrap);wrap.append(svg);let b=document.createElement('button');b.textContent='放大图解';b.onclick=()=>{const clone=svg.cloneNode(true);clone.querySelectorAll('[id]').forEach(n=>n.id='viewer-'+n.id);clone.querySelectorAll('[aria-labelledby]').forEach(n=>n.setAttribute('aria-labelledby','viewer-'+n.getAttribute('aria-labelledby')));clone.querySelectorAll('[marker-end]').forEach(n=>n.setAttribute('marker-end',n.getAttribute('marker-end').replace('#','#viewer-')));document.getElementById('viewer-body').replaceChildren(clone);viewer.showModal();};f.prepend(b)});
let marks=[],current=-1;const input=document.getElementById('query'),status=document.getElementById('search-status');function search(){document.querySelectorAll('article mark').forEach(m=>m.replaceWith(document.createTextNode(m.textContent)));document.querySelector('article').normalize();marks=[];current=-1;const q=input.value.trim();if(!q){status.textContent='';return}const nodes=[],walker=document.createTreeWalker(document.querySelector('article'),NodeFilter.SHOW_TEXT);while(walker.nextNode())if(!walker.currentNode.parentElement.closest('svg,button'))nodes.push(walker.currentNode);for(const n of nodes){const s=n.nodeValue,lo=s.toLowerCase(),needle=q.toLowerCase();let at=0,i=lo.indexOf(needle);if(i<0)continue;const f=document.createDocumentFragment();while(i>=0){f.append(document.createTextNode(s.slice(at,i)));const m=document.createElement('mark');m.textContent=s.slice(i,i+q.length);f.append(m);marks.push(m);at=i+q.length;i=lo.indexOf(needle,at)}f.append(document.createTextNode(s.slice(at)));n.replaceWith(f)}status.textContent=marks.length+'处';next();}function next(){if(!marks.length)return;current=(current+1)%marks.length;marks[current].scrollIntoView({block:'center'});status.textContent=(current+1)+'/'+marks.length;}document.getElementById('find').onclick=search;document.getElementById('next').onclick=next;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search()}};
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}},{rootMargin:'-85px 0px -65% 0px'});document.querySelectorAll('article h2[id^="chapter-"]').forEach(h=>observer.observe(h));}
'''
tracker='<script defer src="https://cloud.umami.is/script.js" data-website-id="8c64c0bf-97e7-4af5-a5bf-f090c52fc4d3"></script>'
page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Spring Boot3.5.16与2.7.18源码学习：27章、27幅机制图、56段固定SHA源码，启动、自动配置、Web、Binder与版本迁移。"><title>Spring Boot源码学习 · 3.5.16 / 2.7.18</title><style>{style}</style>{tracker}</head><body><header class="topbar"><button id="menu" aria-label="展开目录" aria-expanded="false">目录</button><a class="brand" href="../">源码之下</a><div class="search"><input id="query" aria-label="搜索正文" placeholder="搜索正文"><button id="find">查找</button><button id="next">下一处</button><span id="search-status" aria-live="polite"></span></div><button id="theme" aria-label="切换明暗主题">明暗</button></header><aside><div class="nav-head">Spring Boot源码学习</div><div class="nav-note">3.5.16主线 · 2.7.18对照<br>27章 · 27幅图 · 56段真实源码<br><a href="./springboot-offline.zip">下载离线包</a> · <a href="./springboot-examples.zip">实验工程</a></div><nav aria-label="章节目录">{nav}</nav></aside><main><div class="hero"><div class="eyebrow">READING SPRING BOOT SOURCE</div><h1>先串启动旅程，再看容器状态</h1><p>配置源 → 自动配置候选 → Bean定义 → 实例与WebServer → 业务就绪</p><div class="hero-meta"><span>固定3.5.16 / 2.7.18</span><span>Framework6.2.19边界</span><span>27幅内嵌图解</span><span>56段固定SHA源码</span></div><p><a href="#chapter-01">从责任边界开始 →</a></p></div><article>{body}</article><footer>独立源码导读 · 源码版权归原作者 · Apache License2.0 · <a href="./source-notices.txt">归属说明</a> · <a href="./VERIFICATION.md">验证记录</a></footer></main><a class="top" href="#" aria-label="返回顶部">↑ 顶部</a><dialog id="viewer"><button id="viewer-close">关闭图解</button><div id="viewer-body" class="viewer-body"></div></dialog><script>{script}</script></body></html>'''
